<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {service,dataMode} from '../services'
import {useAuth} from '../stores/auth'
import {validateFile,maxFiles,maxBytes,concurrency} from '../domain/files'
import {errorText,formatSize} from '../composables/useData'
import type {Job} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import Icon from '../components/Icon.vue'
interface QueueItem {id:string;file?:File;name:string;path:string;size:number;status:'queued'|'uploading'|'running'|'completed'|'failed'|'canceled';phase:number;jobId?:string;unitId?:string;error?:string;pollError?:boolean}
const auth=useAuth()
const queue=ref<QueueItem[]>([]),drag=ref(false),loading=ref(true),error=ref(''),working=ref(false),active=ref(0),input=ref<HTMLInputElement>(),directory=ref<HTMLInputElement>(),controllers=new Map<string,AbortController>()
const phases=['上传','解析','结构切分','向量化','完成'],hasQueued=computed(()=>queue.value.some(q=>q.status==='queued'))
let mounted=true
function add(files:File[]){error.value='';for(const file of files){if(queue.value.filter(q=>q.status!=='canceled').length>=maxFiles){error.value=`当前队列最多 ${maxFiles} 个文件，请清空已结束任务后继续。`;break}const path=file.webkitRelativePath||file.name;if(path.split(/[\\/]/).some(s=>s==='..')){error.value='文件路径无效';continue}if(queue.value.some(q=>q.path===path&&q.size===file.size&&!['failed','canceled'].includes(q.status)))continue;const reason=validateFile(file);queue.value.push({id:crypto.randomUUID(),file,name:file.name,path,size:file.size,status:reason?'failed':'queued',phase:0,error:reason||undefined})}}
function picked(event:Event){const target=event.target as HTMLInputElement;add(Array.from(target.files||[]));target.value=''}
async function drop(event:DragEvent){drag.value=false;const entries=Array.from(event.dataTransfer?.items||[]).map(i=>(i as any).webkitGetAsEntry?.()).filter(Boolean);if(!entries.some(e=>e.isDirectory)){add(Array.from(event.dataTransfer?.files||[]));return}const files:File[]=[];async function walk(entry:any,path=''){if(files.length>maxFiles)return;if(entry.isFile){const f:File=await new Promise((resolve,reject)=>entry.file(resolve,reject));Object.defineProperty(f,'webkitRelativePath',{value:path+f.name});files.push(f)}else if(entry.isDirectory){const reader=entry.createReader();while(files.length<=maxFiles){const children:any[]=await new Promise((resolve,reject)=>reader.readEntries(resolve,reject));if(!children.length)break;for(const child of children)await walk(child,path+entry.name+'/')}}}try{for(const e of entries)await walk(e);add(files)}catch{error.value='无法读取拖入目录，请使用“选择目录”重试。'}}
function delay(ms:number,signal:AbortSignal){return new Promise<void>((resolve,reject)=>{const abort=()=>{clearTimeout(t);reject(new DOMException('停止','AbortError'))};const t=setTimeout(()=>{signal.removeEventListener('abort',abort);resolve()},ms);if(signal.aborted)abort();else signal.addEventListener('abort',abort,{once:true})})}
function update(item:QueueItem,job:Job){item.jobId=job.id;item.status=job.status;item.phase=job.phase;item.unitId=job.unitId;item.error=job.error}
async function run(item:QueueItem,resume=false){const controller=new AbortController();controllers.set(item.id,controller);active.value++;item.error='';item.pollError=false;try{if(!resume){if(!item.file)throw new Error('请重新选择原文件再重试');item.status='uploading';const job=await service.upload(item.file,item.path,controller.signal);if(controller.signal.aborted||!mounted)return;update(item,job)}let attempts=0;while(mounted&&item.jobId&&item.status==='running'){if(controller.signal.aborted)throw new DOMException('停止','AbortError');const job=await service.job(item.jobId,controller.signal);if(controller.signal.aborted||!mounted)return;update(item,job);if(++attempts>1200)throw new Error('处理时间较长，请稍后刷新获取进度');if(item.status==='running')await delay(800,controller.signal)}}catch(e){if((e as Error).name!=='AbortError'){item.pollError=!!item.jobId&&item.status==='running';item.status='failed';item.error=errorText(e)+(item.pollError?'；任务可能仍在处理，可重新获取进度。':'')}}finally{controllers.delete(item.id);active.value--;if(mounted&&working.value)pump()}}
function pump(){if(!mounted)return;while(active.value<concurrency){const item=queue.value.find(q=>q.status==='queued');if(!item)break;void run(item)}if(!active.value&&!hasQueued.value)working.value=false}
function start(){working.value=true;pump()}
async function cancel(item:QueueItem){item.status='canceled';item.error='';controllers.get(item.id)?.abort();if(item.jobId){try{await service.cancelJob(item.jobId)}catch(e){item.status='failed';item.pollError=true;item.error='取消尚未确认：'+errorText(e)}}}
function retry(item:QueueItem){if(item.pollError&&item.jobId){item.status='running';void run(item,true)}else if(item.file&&!validateFile(item.file)){item.jobId=undefined;item.phase=0;item.status='queued';item.error='';start()}else{error.value='请重新选择有效的原文件。'}}
async function restore(){loading.value=true;error.value='';try{const jobs=await service.list('jobs');for(const job of jobs){const item:QueueItem={id:job.id,name:job.name,path:job.path,size:job.size,status:job.status,phase:job.phase,jobId:job.id,unitId:job.unitId,error:job.error};queue.value.push(item);if(job.status==='running')void run(item,true)}}catch(e){error.value=errorText(e)}finally{loading.value=false}}
onMounted(restore)
onBeforeUnmount(()=>{mounted=false;for(const c of controllers.values())c.abort()})
const stateLabel=(s:QueueItem['status'])=>({queued:'等待开始',uploading:'上传中',running:'处理中',completed:'已完成',failed:'失败',canceled:'已取消'}[s])
</script>
<template><PageHeader title="导入中心" description="将分散的文档整理为可授权、可检索的知识单元。"><button class="btn quiet" :disabled="active>0" @click="queue=queue.filter(q=>['queued','uploading','running'].includes(q.status))">清空已结束任务</button><button class="btn primary" :disabled="!hasQueued||working" @click="start"><Icon name="upload"/>{{working?'正在导入…':'开始导入'}}</button></PageHeader><div class="import-layout"><section class="panel"><div class="dropzone" :class="{over:drag}" @dragover.prevent="drag=true" @dragleave.prevent="drag=false" @drop.prevent="drop"><Icon name="upload" :size="32"/><h2>拖入文件，或整个目录</h2><p>支持 PDF、Markdown、Word、TXT<br>单文件最大 {{maxBytes/1024/1024}} MB，每批最多 {{maxFiles}} 个文件</p><div class="actions"><button class="btn" @click="input?.click()">选择文件</button><button class="btn quiet" @click="directory?.click()">选择目录</button></div><input ref="input" type="file" multiple accept=".pdf,.md,.markdown,.doc,.docx,.txt" hidden @change="picked"><input ref="directory" type="file" webkitdirectory multiple hidden @change="picked"></div></section><aside class="panel import-description"><h2>从文档到知识</h2><ol><li><span>01</span><div><strong>解析文档</strong><p>PDF 等文件由后端调用 MinerU 在线 API。</p></div></li><li><span>02</span><div><strong>统一结构与切分</strong><p>保留章节、页码和来源，再按结构切分检索片段。</p></div></li><li><span>03</span><div><strong>配置授权后使用</strong><p>一份文档对应一个知识单元，片段继承单元权限。</p></div></li></ol></aside><div v-if="dataMode==='demo'" class="notice warning import-wide">本地演示：仅记录文件信息并模拟处理阶段，不上传文件、不读取真实正文、不调用 MinerU 或生成向量。</div><section class="panel import-wide"><div class="panel-head"><h2>导入任务</h2><span class="small faint">{{queue.length}} 项 · 最多 {{concurrency}} 个并发上传</span></div><p v-if="error" role="alert" class="notice error" style="margin-bottom:16px">{{error}}<button v-if="!queue.length" class="text-button" @click="restore">重试</button></p><div v-if="loading" class="empty-inline">正在读取任务…</div><div v-else-if="!queue.length" class="empty-inline">尚未选择文件，已提交的任务将在刷新后恢复。</div><article v-for="item in queue" :key="item.id" class="import-row"><div class="import-file"><Icon name="file"/><div><strong>{{item.name}}</strong><p>{{item.path!==item.name?item.path+' · ':''}}{{formatSize(item.size)}}</p></div><span class="status" :class="item.status==='completed'?'success':item.status==='failed'?'error':''">{{stateLabel(item.status)}}</span></div><div class="import-stepper"><div v-for="(phase,i) in phases" :key="phase" :class="{done:item.phase>i,current:item.status==='running'&&item.phase===i}"><i>{{item.phase>i?'✓':i+1}}</i><span>{{phase}}</span></div></div><p v-if="item.error" class="field-error">{{item.error}}</p><div class="row-actions"><button v-if="['queued','running','uploading'].includes(item.status)" class="text-button" @click="cancel(item)">取消任务</button><button v-if="item.status==='failed'" class="text-button" @click="retry(item)">{{item.pollError?'重新获取进度':'重试'}}</button><RouterLink v-if="item.unitId&&auth.has('knowledge.permissions')&&auth.has('knowledge.read')" :to="`/knowledge/units?grant=${item.unitId}`" class="text-button">配置授权并查看结果 →</RouterLink><span v-else-if="item.unitId" class="small faint">请联系知识管理员配置访问授权。</span></div></article></section></div></template>
<style scoped>.import-layout{display:grid;grid-template-columns:1.4fr 1fr;gap:20px;align-items:stretch}.import-wide{grid-column:1/-1}.dropzone{border:1px dashed #60756a;background:#151b18;min-height:250px;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:16px;text-align:center;padding:24px;border-radius:4px}.dropzone.over{background:#223b30;border-color:var(--accent)}.dropzone>svg{color:var(--accent)}.dropzone p{font-size:12px;color:var(--muted);line-height:1.9}.import-description ol{padding:0;margin:22px 0 0;list-style:none;display:grid;gap:26px}.import-description li{display:flex;gap:16px}.import-description li>span{font-size:11px;color:var(--faint);padding-top:2px}.import-description strong{font-size:13px;font-weight:500}.import-description li p{font-size:12px;line-height:1.9;color:var(--muted);margin-top:7px}.import-row{padding:22px 0;border-top:1px solid var(--line)}.import-file{display:flex;align-items:center;gap:12px}.import-file>div{flex:1;min-width:0}.import-file>svg{color:var(--faint)}.import-file strong{font-size:13px;font-weight:500;overflow-wrap:anywhere}.import-file p{font-size:11px;color:var(--faint);line-height:1.8;margin-top:6px;overflow-wrap:anywhere}.import-stepper{display:grid;grid-template-columns:repeat(5,1fr);margin:24px 0 12px}.import-stepper>div{position:relative;display:flex;align-items:center;gap:9px;color:var(--faint);font-size:11px}.import-stepper>div:after{content:'';height:1px;background:var(--line);flex:1;margin-right:12px}.import-stepper>div:last-child:after{display:none}.import-stepper i{width:20px;height:20px;display:grid;place-items:center;border:1px solid var(--line);font-style:normal;font-size:11px}.import-stepper .done i,.import-stepper .current i{background:var(--accent);color:#12271d}.import-stepper .current{color:var(--accent)}@media(max-width:640px){.import-layout{grid-template-columns:1fr}.dropzone{padding:20px;min-height:270px}.import-stepper>div{flex-direction:column;gap:8px}.import-stepper>div:after{position:absolute;left:calc(50% + 16px);right:calc(-50% + 8px);top:10px;margin:0}.import-description ol{gap:20px}}</style>
